import{_ as l,o as e,c as a,ai as t}from"./chunks/framework.CpsiabEW.js";const P=JSON.parse('{"title":"HTTP 面试题目","description":"","frontmatter":{},"headers":[],"relativePath":"doc/2.Interview/0.Resources/resources-20260317090323/11.Http.md","filePath":"doc/2.Interview/0.Resources/resources-20260317090323/11.Http.md"}'),o={name:"doc/2.Interview/0.Resources/resources-20260317090323/11.Http.md"};function r(n,i,s,T,h,c){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="http-面试题目" tabindex="-1">HTTP 面试题目 <a class="header-anchor" href="#http-面试题目" aria-label="Permalink to “HTTP 面试题目”">​</a></h1><h2 id="http-协议基础-请求-响应" tabindex="-1">HTTP 协议基础（请求/响应） <a class="header-anchor" href="#http-协议基础-请求-响应" aria-label="Permalink to “HTTP 协议基础（请求/响应）”">​</a></h2><ol><li>HTTP 协议是什么？</li><li>HTTP 请求报文和响应报文的结构是什么？</li><li>HTTP 请求报文由哪几部分组成（请求行、请求头、消息体）？</li><li>HTTP 响应报文由哪几部分组成（状态行、响应头、消息体）？</li><li>HTTP 起始行的作用是什么？</li><li>HTTP 头部有哪些常见字段？</li><li>HTTP 消息体的作用是什么？</li><li>完整 HTTP 事务的过程是什么（域名解析、TCP 握手、发送请求、服务器响应、TCP 挥手）？</li></ol><h2 id="http-方法-get、post、put、delete-等" tabindex="-1">HTTP 方法（GET、POST、PUT、DELETE 等） <a class="header-anchor" href="#http-方法-get、post、put、delete-等" aria-label="Permalink to “HTTP 方法（GET、POST、PUT、DELETE 等）”">​</a></h2><ol start="9"><li>HTTP 有哪些常用方法？</li><li>GET 与 POST 请求的区别是什么（传参方式、缓存、安全性、长度限制）？</li><li>PUT 请求的作用是什么？</li><li>DELETE 请求的作用是什么？</li><li>PATCH 请求与 PUT 请求的区别是什么？</li><li>OPTIONS 请求的作用是什么？</li><li>HEAD 请求的作用是什么？</li><li>CONNECT 请求的作用是什么？</li><li>TRACE 请求的作用是什么？</li><li>什么是幂等性？哪些 HTTP 方法是幂等的？</li><li>什么是安全方法？哪些 HTTP 方法是安全的？</li></ol><h2 id="状态码-200、301、404、500-等" tabindex="-1">状态码（200、301、404、500 等） <a class="header-anchor" href="#状态码-200、301、404、500-等" aria-label="Permalink to “状态码（200、301、404、500 等）”">​</a></h2><ol start="20"><li>HTTP 状态码分为哪几类（1xx 信息性、2xx 成功、3xx 重定向、4xx 客户端错误、5xx 服务器错误）？</li><li>200 OK 表示什么？</li><li>201 Created 表示什么？</li><li>204 No Content 表示什么？</li><li>301 Moved Permanently 与 302 Found 的区别是什么？</li><li>304 Not Modified 表示什么？</li><li>307 Temporary Redirect 与 302 的区别是什么？</li><li>308 Permanent Redirect 与 301 的区别是什么？</li><li>400 Bad Request 表示什么？</li><li>401 Unauthorized 与 403 Forbidden 的区别是什么？</li><li>404 Not Found 表示什么？</li><li>405 Method Not Allowed 表示什么？</li><li>500 Internal Server Error 表示什么？</li><li>502 Bad Gateway 表示什么？</li><li>503 Service Unavailable 表示什么？</li><li>504 Gateway Timeout 表示什么？</li></ol><h2 id="请求头与响应头" tabindex="-1">请求头与响应头 <a class="header-anchor" href="#请求头与响应头" aria-label="Permalink to “请求头与响应头”">​</a></h2><ol start="36"><li>常见的 HTTP 请求头有哪些（Content-Type、User-Agent、Accept、Authorization、Cookie 等）？</li><li>常见的 HTTP 响应头有哪些（Set-Cookie、Cache-Control、ETag、Location 等）？</li><li>Content-Type 的作用是什么？</li><li>Content-Length 的作用是什么？</li><li>Content-Encoding 的作用是什么？</li><li>Accept 与 Content-Type 的区别是什么？</li><li>Accept-Encoding 的作用是什么？</li><li>User-Agent 的作用是什么？</li><li>Referer 与 Origin 的区别是什么？</li><li>Host 头部的作用是什么？</li><li>Connection 与 Keep-Alive 的作用是什么？</li><li>Authorization 头部的作用是什么？</li><li>WWW-Authenticate 头部的作用是什么？</li></ol><h2 id="cookie-与-session" tabindex="-1">Cookie 与 Session <a class="header-anchor" href="#cookie-与-session" aria-label="Permalink to “Cookie 与 Session”">​</a></h2><ol start="49"><li>Cookie 是什么？有哪些属性？</li><li>Session 是什么？如何管理？</li><li>Cookie 与 Session 的区别是什么（存储位置、安全性、大小限制）？</li><li>Cookie 的作用域如何设置？</li><li>HttpOnly 属性的作用是什么？</li><li>Secure 属性的作用是什么？</li><li>SameSite 属性的作用是什么？</li><li>Token 与 Session 的区别是什么？</li><li>JWT 是什么？</li><li>JWT 与 Session 的区别是什么？</li><li><code>cookie</code>、<code>sessionStorage</code> 和 <code>localStorage</code> 的区别是什么（存储位置、生命周期、大小限制）？</li></ol><h2 id="缓存机制-强缓存、协商缓存" tabindex="-1">缓存机制（强缓存、协商缓存） <a class="header-anchor" href="#缓存机制-强缓存、协商缓存" aria-label="Permalink to “缓存机制（强缓存、协商缓存）”">​</a></h2><ol start="60"><li>HTTP 缓存机制是什么？</li><li>强缓存与协商缓存的区别是什么？</li><li>如何控制浏览器缓存？</li><li>Cache-Control 有哪些常用指令（max-age、no-cache、no-store）？</li><li>Expires 与 Cache-Control 的区别是什么？</li><li>ETag 与 Last-Modified 的区别是什么？</li><li>If-None-Match 与 If-Modified-Since 的作用是什么？</li><li>缓存位置有哪些（Service Worker、Memory Cache、Disk Cache、Push Cache）？</li><li>如何禁用缓存？</li></ol><h2 id="https-与-ssl-tls" tabindex="-1">HTTPS 与 SSL/TLS <a class="header-anchor" href="#https-与-ssl-tls" aria-label="Permalink to “HTTPS 与 SSL/TLS”">​</a></h2><ol start="69"><li>HTTPS 与 HTTP 的区别及优势是什么（加密传输、需要证书、默认端口 443）？</li><li>HTTPS 的原理及握手过程是什么（基于 TLS/SSL 协议，非对称加密交换对称密钥，再用对称加密传输数据）？</li><li>HTTPS 加密实现原理是什么（对称加密 AES、非对称加密 RSA、数字证书绑定公钥）？</li><li>SSL 与 TLS 的区别是什么？</li><li>数字证书是什么？CA 证书的作用是什么？</li><li>对称加密与非对称加密的区别是什么？</li><li>混合加密的原理是什么？</li><li>数字签名的作用是什么？</li><li>证书链是什么？</li></ol><h2 id="http-2-与-http-3" tabindex="-1">HTTP/2 与 HTTP/3 <a class="header-anchor" href="#http-2-与-http-3" aria-label="Permalink to “HTTP/2 与 HTTP/3”">​</a></h2><ol start="78"><li>HTTP/1.0 与 HTTP/1.1 的区别是什么？</li><li>HTTP/1.1 与 HTTP/2 的区别是什么？</li><li>HTTP/2 的特性及优势有哪些（多路复用、头部压缩 HPACK、服务器推送、优先级队列）？</li><li>什么是多路复用？</li><li>什么是二进制分帧？</li><li>HTTP/2 头部压缩的原理是什么？</li><li>什么是服务器推送？</li><li>HTTP/3 的特性有哪些（基于 QUIC 协议、UDP 传输、解决队头阻塞）？</li><li>QUIC 协议是什么？</li></ol><h2 id="restful-api-设计" tabindex="-1">RESTful API 设计 <a class="header-anchor" href="#restful-api-设计" aria-label="Permalink to “RESTful API 设计”">​</a></h2><ol start="87"><li>RESTful 是什么？</li><li>RESTful API 的设计原则是什么（无状态、资源导向 URL、统一接口 HTTP 方法 + URI + 状态码）？</li><li>RESTful 资源命名规范是什么？</li><li>RESTful 路由设计规范是什么？</li><li>RESTful API 中状态码如何使用？</li><li>RESTful API 版本控制有哪些方式？</li></ol><h2 id="跨域问题与解决方案" tabindex="-1">跨域问题与解决方案 <a class="header-anchor" href="#跨域问题与解决方案" aria-label="Permalink to “跨域问题与解决方案”">​</a></h2><ol start="93"><li>什么是跨域？同源策略是什么？</li><li>跨域产生的原因是什么？</li><li>跨域解决方案有哪些（CORS、JSONP、代理服务器、WebSocket、postMessage）？</li><li>CORS 的原理是什么？</li><li>什么是简单请求？什么是预检请求？</li><li>Access-Control-Allow-Origin 的作用是什么？</li><li>Access-Control-Allow-Credentials 的作用是什么？</li><li>JSONP 的原理是什么？</li><li>JSONP 与 CORS 的区别是什么？</li><li>Nginx 反向代理如何解决跨域？</li><li>postMessage 如何实现跨域通信？</li><li>WebSocket 如何解决跨域问题？</li><li>document.domain 如何解决跨域？</li><li>window.name 如何实现跨域通信？</li></ol><h2 id="tcp-ip-与网络协议" tabindex="-1">TCP/IP 与网络协议 <a class="header-anchor" href="#tcp-ip-与网络协议" aria-label="Permalink to “TCP/IP 与网络协议”">​</a></h2><ol start="107"><li>TCP 与 UDP 的区别及适用场景是什么（面向连接可靠传输 vs 无连接尽最大努力交付）？</li><li>TCP 三次握手的原理是什么（SYN、SYN+ACK、ACK）？</li><li>TCP 四次挥手的原理是什么（FIN、ACK、FIN、ACK）？</li><li>WebSocket 是什么？</li><li>WebSocket 与 HTTP 的区别是什么？</li><li>WebSocket 连接过程是什么？</li><li>长连接与短连接的区别是什么？</li><li>轮询与长轮询的区别是什么？</li><li>SSE（Server-Sent Events）是什么？</li></ol><h2 id="dns-与-cdn" tabindex="-1">DNS 与 CDN <a class="header-anchor" href="#dns-与-cdn" aria-label="Permalink to “DNS 与 CDN”">​</a></h2><ol start="116"><li>DNS 是什么？DNS 解析过程是什么？</li><li>DNS 劫持的原理及防范措施是什么（篡改 DNS 解析结果；使用可信 DNS 服务、启用 DoH/DoT）？</li><li>CDN 加速的实现原理是什么（分布式边缘节点缓存静态资源，用户就近访问）？</li><li>负载均衡的原理是什么？</li><li>反向代理与正向代理的区别是什么？</li></ol><h2 id="浏览器存储" tabindex="-1">浏览器存储 <a class="header-anchor" href="#浏览器存储" aria-label="Permalink to “浏览器存储”">​</a></h2><ol start="121"><li>localStorage 与 sessionStorage 的区别是什么？</li><li>IndexedDB 的适用场景是什么？</li><li>Service Worker 的作用是什么？</li><li>PWA 是什么？</li></ol><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to “安全”">​</a></h2><ol start="125"><li>XSS 攻击是什么？如何防范（输入过滤、输出编码）？</li><li>CSRF 攻击是什么？如何防范（CSRF Token、SameSite Cookie）？</li><li>点击劫持的原理及防范措施是什么？</li></ol><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to “其他”">​</a></h2><ol start="128"><li>XML 与 JSON 的区别是什么？</li><li>从输入网址到页面呈现的完整过程是什么？</li><li>CommonJS 与 ES6 模块的区别是什么（语法 require/module.exports vs import/export、作用域、加载方式）？</li></ol>',31)])])}const S=l(o,[["render",r]]);export{P as __pageData,S as default};
